import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createNode as _ } from '@/primitives'; // placeholder import to satisfy allowed list (no effect)

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry & material for the main card
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff, map: null, transparent: true });
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously; keep reference for cleanup
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // ----- Stock badge (placeholder) -----
  const badgeSize = 0.2;
  const badgeGeom = new PlaneGeometry(badgeSize, badgeSize);
  const badgeMat = new MeshBasicNodeMaterial({
    color: config.visual?.colors?.accent ?? '#ff2a38',
    transparent: true,
    depthTest: false,
  });
  const badge = new Mesh(badgeGeom, badgeMat);
  // Position badge at top‑right corner of the card
  badge.position.set(0.5 - badgeSize / 2, 0.5 - badgeSize / 2, 0.01);
  root.add(badge);
  root.userData.stockBadge = badge;

  // ----- Interaction handlers -----
  // Store original Y to restore on hover out
  const originalY = mesh.position.y;

  // Hover lift (rise‑in) – subtle 0.15 units
  const hoverEnter = () => {
    gsap.to(mesh.position, {
      y: originalY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };
  const hoverLeave = () => {
    gsap.to(mesh.position, {
      y: originalY,
      duration: 0.4,
      ease: 'power2.out',
    });
  };

  // Click emits navigation event
  const onClick = () => {
    ctx.emit('hub-journal.select', {});
  };

  root.userData.handlers = {
    hoverEnter,
    hoverLeave,
    click: onClick,
  };

  // ----- Cleanup -----
  root.userData.cleanup = () => {
    // Dispose geometry & materials
    geometry.dispose();
    material.dispose();
    badgeGeom.dispose();
    badgeMat.dispose();

    // Dispose loaded texture if any
    if (loadedTexture) {
      loadedTexture.dispose();
    }

    // Kill any GSAP tweens related to this node
    gsap.killTweensOf(mesh.position);
    gsap.killTweensOf(badge.position);
  };

  return root;
}
